/// Returns 1.0 if `i == j`, otherwise 0.0.
fn diag_val(i: isize, j: isize) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

/// Constructs an n×n identity matrix of f64 values.
///
/// The returned Vec has `n` rows, each of length `n`.
/// Entry (i, j) is 1.0 if i == j, and 0.0 otherwise.
fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        let mut row = Vec::with_capacity(n);
        for j in 0..n {
            // Cast i, j to signed so we can call diag_val
            row.push(diag_val(i as isize, j as isize));
        }
        matrix.push(row);
    }
    matrix
}

fn main() {
    // Example usage:
    let m0 = identity(0);
    assert_eq!(m0.len(), 0);

    let m1 = identity(1);
    assert_eq!(m1, vec![vec![1.0]]);

    let m3 = identity(3);
    assert_eq!(
        m3,
        vec![
            vec![1.0, 0.0, 0.0],
            vec![0.0, 1.0, 0.0],
            vec![0.0, 0.0, 1.0],
        ]
    );

    println!("All tests passed!");
}